import { DURATION, BPM } from './spec.mjs';

// Original procedural composition, not generated by a paid model or copied from a recording.
// Stateless indexed noise keeps browser playback and offline exports sample-identical.
function noise(index) {
  let n = Math.imul(index + 1, 374761393);
  n = Math.imul(n ^ (n >>> 13), 1274126177);
  return ((n ^ (n >>> 16)) >>> 0) / 2147483648 - 1;
}

export function synthesizeAudio(sampleRate = 48000) {
  if (!Number.isInteger(sampleRate) || sampleRate < 8000 || sampleRate > 96000) {
    throw new RangeError('sampleRate must be an integer from 8000 to 96000');
  }
  const pcm = new Float32Array(DURATION * sampleRate);
  const beatLength = 60 / BPM;
  const notes = [110, 110, 130.8128, 146.8324, 87.3071, 87.3071, 97.9989, 110];
  const tau = Math.PI * 2;
  for (let i = 0; i < pcm.length; i++) {
    const t = i / sampleRate;
    const beat = t / beatLength;
    const whole = Math.floor(beat);
    const phase = (beat - whole) * beatLength;
    const eighth = (beat * 2 % 1) * beatLength / 2;
    const bar = Math.floor(beat / 4);
    const freq = notes[bar % notes.length];
    const active = t < 21;
    let signal = 0;
    if (active) {
      const duck = 1 - 0.72 * Math.exp(-phase * 22);
      const bass = Math.sin(tau * freq * t) + 0.24 * Math.sin(tau * freq * 2 * t);
      signal += bass * 0.14 * duck;
      const arpNote = freq * [2, 3, 4, 3][Math.floor(beat * 2) % 4];
      signal += Math.sin(tau * arpNote * t) * Math.exp(-eighth * 19) * 0.075;
      const kick = Math.sin(tau * (46 * phase + 6.5 * (1 - Math.exp(-phase * 35))));
      signal += kick * Math.exp(-phase * 15) * (whole % 4 === 0 ? 0.65 : 0.44);
      if (whole % 2 === 1) signal += noise(i) * Math.exp(-phase * 28) * 0.2;
      signal += (noise(i + 137) - noise(i + 139)) * Math.exp(-eighth * 100) * 0.055;
      const section = t % 3;
      if (section > 2.65) {
        const rise = (section - 2.65) / 0.35;
        signal += noise(i + 391) * rise * rise * 0.17;
      }
    }
    // Designed impact on each scene cut and the final brand resolve.
    const hitTime = t % 3;
    if (t <= 21.7) {
      signal += Math.sin(tau * (33 * hitTime + 2.6 * (1 - Math.exp(-hitTime * 22)))) * Math.exp(-hitTime * 8) * 0.42;
      signal += noise(i + 2003) * Math.exp(-hitTime * 26) * 0.09;
    }
    if (t >= 21) {
      const tail = t - 21;
      signal += (Math.sin(tau * 220 * t) + 0.5 * Math.sin(tau * 330 * t) + 0.3 * Math.sin(tau * 440 * t)) * Math.exp(-tail * 3) * 0.15;
    }
    const inEnvelope = Math.min(1, t / 0.008);
    const outEnvelope = Math.min(1, Math.max(0, (DURATION - 0.15 - t) / 0.4));
    pcm[i] = Math.tanh(signal * 1.5) * 0.92 * inEnvelope * outEnvelope;
  }
  return pcm;
}
